private TreeNode<T> rotateRight(TreeNode<T> node) {
    // If the node is the root, do nothing and return the root
    if (node.parent == null) {
        return node;
    }

    // If the node is the left child of its parent, perform a right rotation
    if (node.parent.left == node) {
        // Detach the node from its parent and make it a child of its grandfather
