        GrandfatherNode.left.right = node;
        node.parent = GrandfatherNode;

        // Set the heights of the grandfather and node
        GrandfatherNode.height = Math.max(GrandfatherNode.height, Math.max(LeftNode.height, node.height) + 1);
        node.height = Math.max(LeftNode.height, node.height) + 1;

