@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Create a new graph with the same node set as the target graph
    Graph<V, E> completeGraph = new Graph<>();
    for (V v : target.nodes) {
        completeGraph.addNode(v);
    }

    // Add all possible edges to the new graph
    for (V u : target.nodes) {
        for (V v : target.nodes) {
            if (u != v) {
                completeGraph.addEdge(u, v);
            }
        }
    }

    // Map each node in the new graph to its corresponding node in the target graph
    Map<V, V> nodeMap = new HashMap<>();
    for (V v : completeGraph.nodes) {
        nodeMap.put(v, resultMap.get(v.getId()));
    }

    // Set the node ID for each node in the new graph
    int id = 0;
    for (V v : completeGraph.nodes) {
        v.setId(id);
        id++;
    }

    // Return the complete bipartite graph
    return completeGraph;
}

