public static Class[] resolveArguments(Type genericType, Class targetType) {
    // Get the type variables for the target type
    TypeVariable[] typeVariables = targetType.getTypeParameters();

    // Get the actual type arguments for the generic type
    Type[] actualTypeArguments;
    if (genericType instanceof ParameterizedType) {
        actualTypeArguments = ((ParameterizedType) genericType).getActualTypeArguments();
    } else {
        throw new IllegalArgumentException("The generic type must be a parameterized type.");
    }

    // Create a map of type variables to their actual type arguments
    Map<TypeVariable, Type> typeVariableMap = new HashMap<>();
    for (int i = 0; i < actualTypeArguments.length; i++) {
        typeVariableMap.put(typeVariables[i], actualTypeArguments[i]);
    }

    // Resolve the arguments for the target type
    Class[] resolvedArguments = new Class[actualTypeArguments.length];
    for (int i = 0; i < resolvedArguments.length; i++) {
        resolvedArguments[i] = resolveType(typeVariableMap, actualTypeArguments[i]);
    }
    return resolvedArguments;
}

private static Class resolveType(Map<TypeVariable, Type> typeVariableMap, Type type) {
    if (type instanceof Class) {
        return (Class) type;
    } else if (type instanceof TypeVariable) {
        Type bound = ((TypeVariable) type).getBounds()[0];
        return resolveType(typeVariableMap, bound);
    } else if (type instanceof ParameterizedType) {
        Type[] actualTypeArguments = ((ParameterizedType) type).getActualTypeArguments();
        for (Type actualTypeArgument : actualTypeArguments) {
            Class resolvedArgument = resolveType(typeVariableMap, actualTypeArgument);
            if (resolvedArgument != null) {
                return resolvedArgument;
            }
        }
    }
    return null;
}
