static long compressTimeBucket(long timeBucket, int dayStep) {
  int year, month, day;
  // Extract the year and month from the time bucket
  year = (int) (timeBucket / 100000000);
  month = (int) (timeBucket % 100000000) / 100;

  // Extract the day from the time bucket
  day = (int) (timeBucket % 100);

  // Compute the new year and month by adding the dayStep modulo 12
  year += (dayStep / 12);
  month += (dayStep % 12);

  // Wrap around the month if necessary
  if (month > 12) {
    year += 1;
    month -= 12;
  }

  // Compute the new day by adding the dayStep modulo 31
  day += (dayStep % 31);

  // Wrap around the day if necessary
  if (day > 31) {
    month += 1;
    day -= 31;
  }

  // Build the new time bucket
  return year * 100000000 + month * 100 + day;
}
