public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u.getPath() == null) {
        return segments;
    }
    // Ignore leading '/' if the path is an absolute path
    int start = u.getPath().startsWith("/") ? 1 : 0;
    int end = u.getPath().indexOf('?');
    if (end == -1) {
        end = u.getPath().length();
    }
    String path = u.getPath().substring(start, end);
    while (path.length() > 0) {
        int next = path.indexOf('/');
        if (next == -1) {
            next = path.length();
        }
        String segment = path.substring(0, next);
        if (decode) {
            segment = URLDecoder.decode(segment, StandardCharsets.UTF_8);
        }
        segments.add(new PathSegmentImpl(segment));
        path = path.substring(next + 1);
    }
    return segments;
}
