public Class findClass(final String className) throws ClassNotFoundException {
    // Your code here
    ClassLocator classLocator = new ClassLocator();
    ClassLoader classLoader = Thread.currentThread().getContextClassLoader();
    List<URL> classPath = classLocator.getClassPath(classLoader);
    Set<Class<?>> classes = classLocator.findClasses(classPath);
    String searchClass = className.replace('.', '/');
    for (Class<?> clazz : classes) {
        if (clazz.getName().replace('.', '/').equals(searchClass)) {
            return clazz;
        }
    }
    throw new ClassNotFoundException(String.format("Class %s cannot be found", className));
}

class ClassLocator {
    private final String CLASS_EXTENSION = ".class";
    private final String[] resourceSuffixes = {".class", ".jar", ".zip"};

    public List<URL> getClassPath(ClassLoader classLoader) {
        List<URL> classPath = new LinkedList<>();
        Collections.addAll(classPath, classLoader.getURLs());
        return classPath;
    }

    public Set<Class<?>> findClasses(List<URL> classPath) {
        Set<Class<?>> classes = new LinkedHashSet<>();
        for (URL url : classPath) {
            if (url.getPath().endsWith(resourceSuffixes)) {
                findClassesInJar(url, classes);
            } else {
                findClassesInDirectory(new File(url.getPath()), classes);
            }
        }
        return classes;
    }

    public void findClassesInJar(URL url, Set<Class<?>> classes) {
        try ( JarFile jarFile = new JarFile(url.getPath()) ) {
            Set<JarEntry> entries = jarFile.stream().collect(Collectors.toSet());
            for (JarEntry entry : entries) {
                if (entry.getName().endsWith(CLASS_EXTENSION)) {
                    String className = entry.getName().replace('/', '.');
                    Class.forName(className.replace(CLASS_EXTENSION, ""));
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public void findClassesInDirectory(File directory, Set<Class<?>> classes) {
        File[] files = directory.listFiles();
        for (File file : files) {
            if (file.isDirectory()) {
                findClassesInDirectory(file, classes);
            } else if (file.getName().endsWith(CLASS_EXTENSION)) {
                String className = file.getName().replace(CLASS_EXTENSION, "");
                className = className.substring(0, className.lastIndexOf('.'));
                className = className.replace('/', '.');
                Class.forName(className);
            }
        }
    }
}

